where b.del_flag = '0' and p.del_flag = '0' and s.del_flag = '0'

    AND b.program_id = #{programId}


    AND s.country = #{country}


    AND b.source = #{source}


    AND (p.program_name like concat('%', #{programName}, '%') or p.program_name_en ilike concat('%', #{programName}, '%')
         or s.school_name like concat('%', #{programName}, '%') or s.school_name_en ilike concat('%', #{programName}, '%'))

order by s.country, s.school_name, p.program_name, b.benchmark_id

